using DigitalAgriculturalMarketPlace.Data;
using DigitalAgriculturalMarketplace.Constants;
using DigitalAgriculturalMarketplace.Controllers;
using DigitalAgriculturalMarketplace.Models;
using DigitalAgriculturalMarketplace.Services;
using DigitalAgriculturalMarketplace.ViewModels;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Xunit;
namespace DigitalAgriculturalMarketPlace.Tests;

public sealed class Phase5RfqWorkflowTests:IClassFixture<SqlServerTestDatabase>
{
    private readonly SqlServerTestDatabase _database;public Phase5RfqWorkflowTests(SqlServerTestDatabase database)=>_database=database;
    [Fact]public async Task BuyerCreatesMultiItemDraftAndPublishes(){await using var db=_database.CreateContext();var buyer=await User(db,UserRoles.Consumer);var (c1,c2)=await Catalogs(db);var s=Service(db);var result=await s.CreateAsync(buyer.Id,RfqModel(c1.Id,c2.Id));Assert.True(result.Succeeded);var rfq=await db.Rfqs.Include(x=>x.Items).SingleAsync(x=>x.Id==result.OrderId);Assert.Equal(2,rfq.Items.Count);Assert.Equal("Draft",rfq.Status);Assert.True((await s.PublishAsync(rfq.Id,buyer.Id)).Succeeded);Assert.Equal("Open",rfq.Status);}
    [Fact]public async Task BuyerCannotPublishAnotherBuyersRfq(){await using var db=_database.CreateContext();var owner=await User(db,UserRoles.Consumer);var other=await User(db,UserRoles.Consumer);var(c1,c2)=await Catalogs(db);var s=Service(db);var created=await s.CreateAsync(owner.Id,RfqModel(c1.Id,c2.Id));Assert.False((await s.PublishAsync(created.OrderId!.Value,other.Id)).Succeeded);}
    [Fact]public async Task SellerCannotQuoteOwnRfq(){await using var db=_database.CreateContext();var buyer=await User(db,UserRoles.Consumer);var(c1,c2)=await Catalogs(db);var s=Service(db);var created=await s.CreateAsync(buyer.Id,RfqModel(c1.Id,c2.Id));await s.PublishAsync(created.OrderId!.Value,buyer.Id);Assert.False((await s.SubmitQuotationAsync(buyer.Id,new(){RfqId=created.OrderId.Value,Items=[]})).Succeeded);}
    [Fact]public async Task RetiredOrUnmappedListingIsIneligible(){await using var db=_database.CreateContext();var setup=await SetupOpen(db);setup.Product.IsActive=false;await db.SaveChangesAsync();var model=QuoteModel(setup.Rfq,setup.Product);Assert.False((await Service(db).SubmitQuotationAsync(setup.Seller.Id,model)).Succeeded);}
    [Fact]public async Task QuotationSubmissionDoesNotReserveInventory(){await using var db=_database.CreateContext();var x=await SetupOpen(db);var result=await Service(db).SubmitQuotationAsync(x.Seller.Id,QuoteModel(x.Rfq,x.Product));Assert.True(result.Succeeded);Assert.Equal(10,(await db.Products.FindAsync(x.Product.Id))!.AvailableQuantity);Assert.Equal(0,await db.InventoryReservations.CountAsync(r=>r.ProductId==x.Product.Id));}
    [Fact]public async Task SellerCanWithdrawUnacceptedQuotation(){await using var db=_database.CreateContext();var x=await SetupOpen(db);var s=Service(db);var submitted=await s.SubmitQuotationAsync(x.Seller.Id,QuoteModel(x.Rfq,x.Product));Assert.True((await s.WithdrawAsync(submitted.OrderId!.Value,x.Seller.Id)).Succeeded);Assert.Equal("Withdrawn",(await db.Quotations.FindAsync(submitted.OrderId.Value))!.Status);}
    [Fact]public async Task ExpiredQuotationCannotBeAccepted(){await using var db=_database.CreateContext();var x=await SetupOpen(db);var s=Service(db);var m=QuoteModel(x.Rfq,x.Product);m.ValidUntil=DateTime.Today.AddDays(-1);var submitted=await s.SubmitQuotationAsync(x.Seller.Id,m);var item=await db.QuotationItems.SingleAsync(i=>i.QuotationId==submitted.OrderId);Assert.False((await s.AcceptAsync(x.Buyer.Id,new(){QuotationItemId=item.Id,Quantity=1,OperationKey=Guid.NewGuid().ToString()})).Succeeded);}
    [Fact]public async Task PartialAcceptanceCreatesOrderReservationSnapshotAndMovement(){await using var db=_database.CreateContext();var x=await SetupOpen(db);var(s,qitem)=await Submit(db,x);var accepted=await s.AcceptAsync(x.Buyer.Id,new(){QuotationItemId=qitem.Id,Quantity=4,OperationKey=Guid.NewGuid().ToString()});Assert.True(accepted.Succeeded);var order=await db.Orders.Include(o=>o.Items).SingleAsync(o=>o.Id==accepted.OrderId);Assert.Equal(x.Seller.Id,order.SellerId);Assert.Equal(4,order.Items.Single().Quantity);Assert.Equal(20,order.Items.Single().UnitPrice);Assert.True(await db.InventoryReservations.AnyAsync(r=>r.OrderItemId==order.Items.Single().Id&&r.Status=="Active"));Assert.True(await db.InventoryMovements.AnyAsync(m=>m.ReferenceType=="RfqAllocation"&&m.ReferenceId==qitem.Id));}
    [Fact]public async Task RepeatedPartialAcceptanceRespectsBothLimits(){await using var db=_database.CreateContext();var x=await SetupOpen(db);var(s,item)=await Submit(db,x);Assert.True((await s.AcceptAsync(x.Buyer.Id,new(){QuotationItemId=item.Id,Quantity=4,OperationKey=Guid.NewGuid().ToString()})).Succeeded);Assert.True((await s.AcceptAsync(x.Buyer.Id,new(){QuotationItemId=item.Id,Quantity=4,OperationKey=Guid.NewGuid().ToString()})).Succeeded);Assert.False((await s.AcceptAsync(x.Buyer.Id,new(){QuotationItemId=item.Id,Quantity=3,OperationKey=Guid.NewGuid().ToString()})).Succeeded);Assert.Equal(8,(await db.QuotationItems.FindAsync(item.Id))!.AcceptedQuantity);}
    [Fact]public async Task DuplicateAcceptanceCreatesOneAllocationOrderAndNotificationSet(){await using var db=_database.CreateContext();var x=await SetupOpen(db);var(s,item)=await Submit(db,x);var key="allocation-"+Guid.NewGuid();var a=await s.AcceptAsync(x.Buyer.Id,new(){QuotationItemId=item.Id,Quantity=2,OperationKey=key});var b=await s.AcceptAsync(x.Buyer.Id,new(){QuotationItemId=item.Id,Quantity=2,OperationKey=key});Assert.True(a.Succeeded);Assert.True(b.Succeeded);Assert.Equal(a.OrderId,b.OrderId);Assert.Equal(1,await db.QuotationAllocations.CountAsync(z=>z.OperationKey==key));Assert.Equal(2,await db.Notifications.CountAsync(n=>n.OperationKey!=null&&n.OperationKey.EndsWith(key)));}
    [Fact]public async Task InsufficientInventoryRollsBackAllocation(){await using var db=_database.CreateContext();var x=await SetupOpen(db);x.Product.AvailableQuantity=1;x.Product.Quantity=1;await db.SaveChangesAsync();var(s,item)=await Submit(db,x);Assert.False((await s.AcceptAsync(x.Buyer.Id,new(){QuotationItemId=item.Id,Quantity=2,OperationKey=Guid.NewGuid().ToString()})).Succeeded);Assert.False(await db.QuotationAllocations.AnyAsync(a=>a.QuotationItemId==item.Id));Assert.False(await db.Orders.AnyAsync(o=>o.ProductId==x.Product.Id));}
    [Fact]public async Task FractionalAcceptanceCreatesExactOrderAndAllocation(){await using var db=_database.CreateContext();var x=await SetupOpen(db);var(s,item)=await Submit(db,x);var result=await s.AcceptAsync(x.Buyer.Id,new(){QuotationItemId=item.Id,Quantity=1.5m,OperationKey=Guid.NewGuid().ToString()});Assert.True(result.Succeeded);Assert.Equal(1.5m,(await db.Orders.FindAsync(result.OrderId))!.Quantity);Assert.Equal(1.5m,(await db.QuotationAllocations.SingleAsync(a=>a.OrderId==result.OrderId)).AcceptedQuantity);}
    [Fact]public async Task CompetingSellerCannotReadPrivateQuotation(){await using var db=_database.CreateContext();var x=await SetupOpen(db);var(s,item)=await Submit(db,x);var competitor=await User(db,UserRoles.Farmer);var controller=Controller(db,s,competitor);Assert.IsType<NotFoundResult>(await controller.QuotationDetails(item.QuotationId));var buyerController=Controller(db,s,x.Buyer);Assert.IsType<ViewResult>(await buyerController.QuotationDetails(item.QuotationId));}
    [Fact]public async Task TwoSellersProduceSeparateOrders(){await using var db=_database.CreateContext();var x=await SetupOpen(db);var(s,item1)=await Submit(db,x);var seller2=await User(db,UserRoles.Farmer);await Profile(db,seller2);var p2=await ProductFor(db,seller2,x.Product.CatalogProductId!.Value);var q2=await s.SubmitQuotationAsync(seller2.Id,QuoteModel(x.Rfq,p2));var item2=await db.QuotationItems.SingleAsync(i=>i.QuotationId==q2.OrderId);var a=await s.AcceptAsync(x.Buyer.Id,new(){QuotationItemId=item1.Id,Quantity=3,OperationKey=Guid.NewGuid().ToString()});var b=await s.AcceptAsync(x.Buyer.Id,new(){QuotationItemId=item2.Id,Quantity=2,OperationKey=Guid.NewGuid().ToString()});Assert.NotEqual(a.OrderId,b.OrderId);Assert.Equal(2,await db.Orders.CountAsync(o=>o.Id==a.OrderId||o.Id==b.OrderId));}
    [Fact]public async Task SellerCanSaveEditAndSubmitQuotationDraft(){await using var db=_database.CreateContext();var x=await SetupOpen(db);var s=Service(db);var saved=await s.SubmitQuotationAsync(x.Seller.Id,QuoteModel(x.Rfq,x.Product),false);Assert.Equal("Draft",(await db.Quotations.FindAsync(saved.OrderId))!.Status);var edit=QuoteModel(x.Rfq,x.Product);edit.Id=saved.OrderId!.Value;edit.Items[0].UnitPrice=22;Assert.True((await s.UpdateQuotationDraftAsync(x.Seller.Id,edit)).Succeeded);Assert.Equal(22,(await db.QuotationItems.SingleAsync(i=>i.QuotationId==edit.Id)).UnitPrice);Assert.True((await s.SubmitDraftAsync(saved.OrderId.Value,x.Seller.Id)).Succeeded);Assert.Equal("Submitted",(await db.Quotations.FindAsync(saved.OrderId.Value))!.Status);}
    [Fact]public async Task BuyerCanEditOnlyDraftRfq(){await using var db=_database.CreateContext();var buyer=await User(db,UserRoles.Consumer);var(c1,c2)=await Catalogs(db);var s=Service(db);var made=await s.CreateAsync(buyer.Id,RfqModel(c1.Id,c2.Id));var edit=RfqModel(c1.Id,c2.Id);edit.Id=made.OrderId!.Value;edit.Title="Updated bulk harvest";Assert.True((await s.UpdateDraftAsync(buyer.Id,edit)).Succeeded);Assert.Equal("Updated bulk harvest",(await db.Rfqs.FindAsync(edit.Id))!.Title);await s.PublishAsync(edit.Id,buyer.Id);Assert.False((await s.UpdateDraftAsync(buyer.Id,edit)).Succeeded);}
    [Fact]public async Task ConcurrentAllocationAttemptsCannotOversell(){int buyerId,itemId,productId;await using(var seed=_database.CreateContext()){var x=await SetupOpen(seed);var(_,item)=await Submit(seed,x);buyerId=x.Buyer.Id;itemId=item.Id;productId=x.Product.Id;}async Task<bool>Run(){try{await using var db=_database.CreateContext();return(await Service(db).AcceptAsync(buyerId,new(){QuotationItemId=itemId,Quantity=6,OperationKey=Guid.NewGuid().ToString()})).Succeeded;}catch{return false;}}var outcomes=await Task.WhenAll(Task.Run(Run),Task.Run(Run));await using var check=_database.CreateContext();var itemSaved=await check.QuotationItems.FindAsync(itemId);var product=await check.Products.FindAsync(productId);Assert.True(outcomes.Count(x=>x)<=1);Assert.True(itemSaved!.AcceptedQuantity<=itemSaved.OfferedQuantity);Assert.True(product!.AvailableQuantity>=0);Assert.Equal(outcomes.Count(x=>x),await check.QuotationAllocations.CountAsync(a=>a.QuotationItemId==itemId));}

    private static RfqWorkflowService Service(ApplicationDbContext db)=>new(db,new InventoryService(db));
    private static RfqsController Controller(ApplicationDbContext db,RfqWorkflowService s,User u){var c=new RfqsController(db,s);var http=new DefaultHttpContext{Session=new TestSession()};http.Session.SetInt32("UserId",u.Id);c.ControllerContext=new(){HttpContext=http};c.TempData=new TempDataDictionary(http,new TestTempDataProvider());return c;}
    private static RfqCreateViewModel RfqModel(int c1,int c2)=>new(){Title="Bulk harvest",DeliveryLocation="Central warehouse",RequiredByDate=DateTime.Today.AddDays(10),Items=[new(){CatalogProductId=c1,UnitOfMeasureId=1,RequestedQuantity=10},new(){CatalogProductId=c2,UnitOfMeasureId=1,RequestedQuantity=5}]};
    private static QuotationCreateViewModel QuoteModel(Rfq r,Product p)=>new(){RfqId=r.Id,ValidUntil=DateTime.Today.AddDays(5),Items=[new(){RfqItemId=r.Items.First(i=>i.CatalogProductId==p.CatalogProductId).Id,ProductId=p.Id,OfferedQuantity=10,UnitPrice=20,EstimatedDeliveryDate=DateTime.Today.AddDays(3)}]};
    private static async Task<(RfqWorkflowService Service,QuotationItem Item)> Submit(ApplicationDbContext db,(User Buyer,User Seller,Rfq Rfq,Product Product)x){var s=Service(db);var q=await s.SubmitQuotationAsync(x.Seller.Id,QuoteModel(x.Rfq,x.Product));return(s,await db.QuotationItems.SingleAsync(i=>i.QuotationId==q.OrderId));}
    private static async Task<(User Buyer,User Seller,Rfq Rfq,Product Product)> SetupOpen(ApplicationDbContext db){var buyer=await User(db,UserRoles.Consumer);var seller=await User(db,UserRoles.Farmer);await Profile(db,seller);var(c1,c2)=await Catalogs(db);var s=Service(db);var made=await s.CreateAsync(buyer.Id,RfqModel(c1.Id,c2.Id));await s.PublishAsync(made.OrderId!.Value,buyer.Id);var rfq=await db.Rfqs.Include(r=>r.Items).SingleAsync(r=>r.Id==made.OrderId);var p=await ProductFor(db,seller,c1.Id);return(buyer,seller,rfq,p);}
    private static async Task<(CatalogProduct,CatalogProduct)> Catalogs(ApplicationDbContext db){async Task<CatalogProduct>Add(string n){var c=new CatalogProduct{Name=n+Guid.NewGuid(),Category="Grain",Description="Approved",DefaultUnitId=1,Status="Approved",IsActive=true,CreatedAt=DateTime.UtcNow,UpdatedAt=DateTime.UtcNow};db.CatalogProducts.Add(c);await db.SaveChangesAsync();return c;}return(await Add("Wheat"),await Add("Rice"));}
    private static async Task<Product> ProductFor(ApplicationDbContext db,User seller,int catalog){var p=new Product{Name="Eligible crop",Category="Grain",PricePerUnit=20,Quantity=10,AvailableQuantity=10,ReservedQuantity=0,FarmerId=seller.Id,CatalogProductId=catalog,UnitOfMeasureId=1,IsActive=true,ListedAt=DateTime.UtcNow};db.Products.Add(p);await db.SaveChangesAsync();return p;}
    private static async Task Profile(ApplicationDbContext db,User u){db.SellerProfiles.Add(new(){UserId=u.Id,DisplayName="Seller",IsActive=true,VerificationStatus="Unverified",CreatedAt=DateTime.UtcNow,UpdatedAt=DateTime.UtcNow});await db.SaveChangesAsync();}
    private static async Task<User> User(ApplicationDbContext db,string role){var u=new User{Name="RFQ user",Email=Guid.NewGuid()+"@rfq.test",Phone="0",PasswordHash="x",UserType=role,IsActive=true,CreatedAt=DateTime.UtcNow};db.Users.Add(u);await db.SaveChangesAsync();return u;}
}
